import { test, expect, type Page, type APIRequestContext } from '@playwright/test'
async function login(page: Page) {
  await page.goto('/login'); await page.getByLabel('Adresse e-mail', { exact: true }).fill('erp-admin@local.invalid'); await page.getByLabel('Mot de passe', { exact: true }).fill('Local-Horizon-test-only-2026!'); await page.getByRole('button', { name: 'Se connecter', exact: true }).click(); await expect(page).toHaveURL('/')
}
async function fixture(page: Page, request: APIRequestContext, label: string) {
  await login(page)
  const token = await page.evaluate(() => sessionStorage.getItem('horizon.auth.token') || '')
  const api = async (path: string, data?: object) => { const response = await request.fetch(`http://127.0.0.1:18090/api/${path}`, { method: data ? 'POST' : 'GET', headers: { Authorization: token }, ...(data ? { data } : {}) }); expect(response.status(), await response.text()).toBe(200); return response.json() }
  await page.goto('/contacts/companies/new'); await page.getByLabel('Nom usuel', { exact: true }).fill(label); await page.getByRole('button', { name: 'Enregistrer', exact: true }).click(); await expect(page).toHaveURL(/contacts\/companies\/(?!new)/)
  const company = new URL(page.url()).pathname.split('/').at(-1)!
  await api('collections/contacts_addresses/records', { company, type: 'billing', line1: 'Rue de test', city: 'Paris', postal_code: '75001', country: 'FR', is_primary: true })
  const stages = await api('collections/crm_stages/records'), session = await api('collections/core_users/auth-refresh', {})
  await api('horizon/crm/save', { creation_key: crypto.randomUUID(), input: { title: label, company, contact: '', owner: session.record.id, stage: stages.items[0].id, type: 'direct', estimated_value: 1000, estimated_cost: 0, currency: 'EUR', probability: 0, expected_date: '', description: '', status: 'open', market_types: [] } })
  const settings = await api('horizon/billing/settings'); settings.issuer = { ...settings.issuer, name: 'CVS Engineering Recette', address: 'Rue de test', city: 'Paris', postal_code: '75001', country: 'FR', siret: '00000000000000', vat_number: 'FR00000000000', late_payment_notice: 'Selon conditions contractuelles.' }; await api('horizon/billing/settings', settings)
  return { api, company, token }
}
async function manual(page: Page, label: string, supplier = false) {
  await page.goto(`/billing/${supplier ? 'supplier' : 'customer'}/new`)
  await page.getByRole('combobox', { name: supplier ? 'Fournisseur de la facture' : 'Client de la facture', exact: true }).click(); await page.getByRole('option', { name: label, exact: true }).click()
  await page.getByLabel('Objet', { exact: true }).fill(`Facture ${label}`)
  await page.getByLabel('Date de livraison ou prestation', { exact: true }).fill('2026-10-13')
  await page.getByLabel('Description ligne 1', { exact: true }).pressSequentially('Installation complète')
  await expect(page.getByLabel('Description ligne 1', { exact: true })).toHaveValue('Installation complète')
  await page.getByLabel('Prix HT ligne 1', { exact: true }).fill('100')
  await page.getByRole('button', { name: 'Ventiler', exact: true }).click()
  await page.getByRole('button', { name: 'Ajouter une affectation', exact: true }).click()
  await page.getByRole('combobox', { name: 'Compte analytique 1', exact: true }).click(); await page.getByRole('option').filter({ hasText: label }).first().click()
  await page.getByRole('button', { name: 'Fermer', exact: true }).first().click()
}
